{
  "items": [
    {
      "name": "Finsupp.multinomial",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "definition",
      "type": "{α : Type u_1} → (α →₀ ℕ) → ℕ"
    },
    {
      "name": "Nat.multinomial",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "definition",
      "type": "{α : Type u_1} → Finset α → (α → ℕ) → ℕ"
    },
    {
      "name": "Finsupp.multinomial_update",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (a : α) (f : α →₀ ℕ), f.multinomial = (f.sum fun x => id).choose (f a) * (f.update a 0).multinomial"
    },
    {
      "name": "Finset.prod_pow_choose_succ",
      "module_name": "Mathlib.Data.Nat.Choose.Sum",
      "kind": "theorem",
      "type": "∀ {M : Type u_2} [inst : CommMonoid M] (f : ℕ → ℕ → M) (n : ℕ),\n  ∏ i ∈ Finset.range (n + 2), f i (n + 1 - i) ^ (n + 1).choose i =\n    (∏ i ∈ Finset.range (n + 1), f i (n + 1 - i) ^ n.choose i) *\n      ∏ i ∈ Finset.range (n + 1), f (i + 1) (n - i) ^ n.choose i"
    },
    {
      "name": "Finsupp.multinomial_eq",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (f : α →₀ ℕ), f.multinomial = Nat.multinomial f.support ⇑f"
    },
    {
      "name": "Nat.binomial_eq_choose",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {f : α → ℕ} {a b : α} [inst : DecidableEq α],\n  a ≠ b → Nat.multinomial {a, b} f = (f a + f b).choose (f a)"
    },
    {
      "name": "Nat.multinomial_cons",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {s : Finset α} {a : α} (ha : a ∉ s) (f : α → ℕ),\n  Nat.multinomial (Finset.cons a s ha) f = (f a + ∑ i ∈ s, f i).choose (f a) * Nat.multinomial s f"
    },
    {
      "name": "Nat.multinomial_insert",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {s : Finset α} {a : α} [inst : DecidableEq α],\n  a ∉ s → ∀ (f : α → ℕ), Nat.multinomial (insert a s) f = (f a + ∑ i ∈ s, f i).choose (f a) * Nat.multinomial s f"
    },
    {
      "name": "Finsupp.multinomial_eq_of_support_subset",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {f : α →₀ ℕ} {s : Finset α}, f.support ⊆ s → f.multinomial = Nat.multinomial s ⇑f"
    },
    {
      "name": "Nat.multinomial_univ_two",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ (a b : ℕ), Nat.multinomial Finset.univ ![a, b] = (a + b).factorial / (a.factorial * b.factorial)"
    },
    {
      "name": "Nat.binomial_spec",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {f : α → ℕ} {a b : α} [inst : DecidableEq α],\n  a ≠ b → (f a).factorial * (f b).factorial * Nat.multinomial {a, b} f = (f a + f b).factorial"
    },
    {
      "name": "Nat.multinomial_spec",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (s : Finset α) (f : α → ℕ), (∏ i ∈ s, (f i).factorial) * Nat.multinomial s f = (∑ i ∈ s, f i).factorial"
    },
    {
      "name": "BinomialRing.multichoose",
      "module_name": "Mathlib.RingTheory.Binomial",
      "kind": "definition",
      "type": "{R : Type u_1} → {inst : AddCommMonoid R} → {inst_1 : Pow R ℕ} → [self : BinomialRing R] → R → ℕ → R"
    },
    {
      "name": "Finset.sum_choose_succ_nsmul",
      "module_name": "Mathlib.Data.Nat.Choose.Sum",
      "kind": "theorem",
      "type": "∀ {M : Type u_2} [inst : AddCommMonoid M] (f : ℕ → ℕ → M) (n : ℕ),\n  ∑ i ∈ Finset.range (n + 2), (n + 1).choose i • f i (n + 1 - i) =\n    ∑ i ∈ Finset.range (n + 1), n.choose i • f i (n + 1 - i) +\n      ∑ i ∈ Finset.range (n + 1), n.choose i • f (i + 1) (n - i)"
    },
    {
      "name": "Ring.multichoose",
      "module_name": "Mathlib.RingTheory.Binomial",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : AddCommMonoid R] → [inst_1 : Pow R ℕ] → [BinomialRing R] → R → ℕ → R"
    },
    {
      "name": "Nat.binomial_eq",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {f : α → ℕ} {a b : α} [inst : DecidableEq α],\n  a ≠ b → Nat.multinomial {a, b} f = (f a + f b).factorial / ((f a).factorial * (f b).factorial)"
    },
    {
      "name": "Nat.instBinomialRing",
      "module_name": "Mathlib.RingTheory.Binomial",
      "kind": "instance",
      "type": "BinomialRing ℕ"
    },
    {
      "name": "Nat.multinomial_empty",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (f : α → ℕ), Nat.multinomial ∅ f = 1"
    },
    {
      "name": "Nat.multinomial_pos",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (s : Finset α) (f : α → ℕ), 0 < Nat.multinomial s f"
    },
    {
      "name": "Nat.multinomial_congr",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {s : Finset α} {f g : α → ℕ}, (∀ a ∈ s, f a = g a) → Nat.multinomial s f = Nat.multinomial s g"
    }
  ]
}
